'use client'

import { useEffect, useState } from 'react'
import { initialTelemetry, type SafetyLevel, type Telemetry } from '@/lib/edgeguard'

/**
 * 模拟实时遥测流。后续替换为 ENDPOINTS.telemetryWS 的 WebSocket 订阅，
 * onmessage 时 setState 即可，界面无需改动。
 */
export function useTelemetry() {
  const [telemetry, setTelemetry] = useState<Telemetry>(initialTelemetry)

  useEffect(() => {
    const id = setInterval(() => {
      setTelemetry((prev) => {
        const drift = (n: number, min: number, max: number) =>
          Math.min(max, Math.max(min, Math.round(n + (Math.random() - 0.5) * 8)))
        const attention = drift(prev.attention, 55, 99)
        const fatigue = drift(prev.fatigue, 8, 70)
        const gazeOnRoad = drift(prev.gazeOnRoad, 70, 99)
        const level: SafetyLevel =
          attention < 65 || fatigue > 55 ? 'danger' : attention < 80 || fatigue > 40 ? 'warn' : 'safe'
        return { attention, fatigue, gazeOnRoad, blinkRate: drift(prev.blinkRate, 8, 24), level }
      })
    }, 3000)
    return () => clearInterval(id)
  }, [])

  return telemetry
}
