'use client'

import { Shield, ChartBar, Settings, ChevronLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PanelKey = 'safety' | 'stats' | 'settings'

const items: { key: PanelKey; label: string; icon: typeof Shield }[] = [
  { key: 'safety', label: '安全监控', icon: Shield },
  { key: 'stats', label: '驾驶统计', icon: ChartBar },
  { key: 'settings', label: '设置', icon: Settings },
]

export function AppSidebar({
  active,
  onSelect,
  collapsed,
  onToggle,
}: {
  active: PanelKey
  onSelect: (key: PanelKey) => void
  collapsed: boolean
  onToggle: () => void
}) {
  return (
    <nav
      className={cn(
        'flex shrink-0 flex-col items-stretch gap-2 border-r border-border bg-card/60 py-3 transition-all duration-300',
        collapsed ? 'w-14 px-1.5' : 'w-16 px-2',
      )}
      aria-label="主导航"
    >
      <div className="mb-2 flex items-center justify-center">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/15 ring-1 ring-primary/30">
          <Shield className="h-5 w-5 text-primary" />
        </div>
      </div>

      <div className="flex flex-1 flex-col gap-2">
        {items.map(({ key, label, icon: Icon }) => {
          const isActive = active === key
          return (
            <button
              key={key}
              type="button"
              onClick={() => onSelect(key)}
              aria-label={label}
              aria-current={isActive ? 'page' : undefined}
              className={cn(
                'group relative flex h-14 flex-col items-center justify-center gap-1 rounded-xl transition-colors',
                isActive
                  ? 'bg-primary/12 text-primary'
                  : 'text-muted-foreground hover:bg-secondary hover:text-foreground',
              )}
            >
              {isActive && (
                <span className="absolute left-0 top-1/2 h-7 w-1 -translate-y-1/2 rounded-r-full bg-primary" />
              )}
              <Icon className="h-5 w-5" />
              <span className="text-[10px] leading-none">{label}</span>
            </button>
          )
        })}
      </div>

      <button
        type="button"
        onClick={onToggle}
        aria-label={collapsed ? '展开侧栏' : '收起侧栏'}
        className="flex h-11 items-center justify-center rounded-xl text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground"
      >
        {collapsed ? <ChevronRight className="h-5 w-5" /> : <ChevronLeft className="h-5 w-5" />}
      </button>
    </nav>
  )
}
