'use client'

import { useMemo, useState, useEffect, useCallback } from 'react'
import { AlertTriangle, Camera, CircleCheck, Hand, Radio, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { gestureCommands, type GestureCategory, type GestureDetection } from '@/lib/edgeguard'

// TODO: WebSocket 适配 — 订阅 /ws/gestures
// 消息格式: { type: "gesture_detection", data: GestureDetection }
// 需与 backend/app/camera.py 的 gesture 状态推送对齐
// 几何分类器: modules/vision/gesture_classifier.py → GESTURE_ACTION_MAP
// 决策映射: modules/ai/local_decision_engine.py → GESTURE_MAP

const categories: Array<'全部' | GestureCategory> = ['全部', '空调', '确认', '模式', '导航', '媒体', '通信', '安全']

// 每个手势对应的后端 API 端点
const endpointMap: Record<string, string> = {
  TurnOnAC: '/api/ac/command',
  TurnOffAC: '/api/ac/command',
  confirm: '/api/agent/chat',
  cancel: '/api/agent/chat',
  attention: '/api/agent/chat',
  mode_3: '/api/agent/chat',
  mode_4: '/api/agent/chat',
  zoom_in: '/api/agent/chat',
  previous_track: '/api/music/prev',
  next_track: '/api/music/next',
  volume_up: '/api/music/volume',
  volume_down: '/api/music/volume',
  call: '/api/agent/chat',
  mute: '/api/music/volume',
  emergency_stop: '/api/agent/chat',
}

interface GestureControlProps {
  detection?: GestureDetection | null
  enabled?: boolean
  onToggle?: (enabled: boolean) => void
}

export function GestureControl({ detection, enabled: propEnabled, onToggle }: GestureControlProps) {
  const [internalEnabled, setInternalEnabled] = useState(true)
  const enabled = propEnabled ?? internalEnabled
  const setEnabled = onToggle ?? setInternalEnabled

  const [category, setCategory] = useState<(typeof categories)[number]>('全部')
  const [confirmStop, setConfirmStop] = useState(false)
  const [confirmTimer, setConfirmTimer] = useState(5)
  const [lastExecuted, setLastExecuted] = useState<string | null>(null)

  const filtered = useMemo(
    () => category === '全部' ? gestureCommands : gestureCommands.filter((g) => g.category === category),
    [category],
  )

  // 检测到 emergency_stop 时弹出二次确认
  useEffect(() => {
    if (detection?.gesture === 'stop' && detection?.status === '待确认') {
      setConfirmStop(true)
      setConfirmTimer(5)
    }
  }, [detection])

  // 倒计时自动取消
  useEffect(() => {
    if (!confirmStop) return
    if (confirmTimer <= 0) { setConfirmStop(false); return }
    const t = setTimeout(() => setConfirmTimer((v) => v - 1), 1000)
    return () => clearTimeout(t)
  }, [confirmStop, confirmTimer])

  const handleConfirmStop = useCallback(() => {
    setConfirmStop(false)
    setLastExecuted('stop → emergency_stop → 已触发')
  }, [])

  const handleCancelStop = useCallback(() => {
    setConfirmStop(false)
    setLastExecuted('stop → emergency_stop → 已取消')
  }, [])

  // 动态识别状态
  const gestureName = detection?.gesture || '—'
  const confidence = detection?.confidence ?? null
  const detStatus = detection?.status ?? '识别中'

  return (
    <div className="flex h-full min-h-0 flex-col gap-3">
      {/* 确认覆盖层：emergency_stop 二次确认 */}
      {confirmStop && (
        <div className="absolute inset-0 z-50 flex flex-col items-center justify-center gap-4 rounded-2xl bg-background/95 backdrop-blur-md animate-hmi-pulse">
          <AlertTriangle className="h-12 w-12 text-danger" />
          <div className="text-center">
            <p className="text-lg font-bold text-danger">确认紧急制动？</p>
            <p className="mt-1 text-sm text-muted-foreground">
              此操作将触发最高级别安全告警
            </p>
            <p className="mt-2 font-mono text-2xl font-semibold text-danger">
              {confirmTimer}s 后自动取消
            </p>
          </div>
          <div className="flex gap-4">
            <button
              type="button"
              onClick={handleCancelStop}
              className="flex h-14 w-32 items-center justify-center rounded-2xl bg-secondary text-lg font-medium text-muted-foreground hover:bg-accent hover:text-foreground"
            >
              取消
            </button>
            <button
              type="button"
              onClick={handleConfirmStop}
              className="flex h-14 w-32 items-center justify-center rounded-2xl bg-danger text-lg font-bold text-primary-foreground hover:opacity-90 animate-hmi-breathe"
            >
              确认制动
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-[1fr_1.25fr] gap-3">
        {/* 摄像头状态 */}
        <div className="relative flex min-h-28 flex-col justify-between overflow-hidden rounded-2xl bg-secondary/70 p-4 ring-1 ring-border">
          <Camera className="absolute right-3 top-3 h-16 w-16 text-primary/10" />
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <span className={cn('h-2 w-2 rounded-full', enabled ? 'animate-hmi-breathe bg-safe' : 'bg-muted-foreground')} />
            Geometry 分类器 {enabled ? '在线' : '已暂停'}
          </div>
          <div>
            <div className={cn('font-mono text-xl font-semibold', gestureName !== '—' ? 'text-primary' : 'text-muted-foreground')}>
              {gestureName}
            </div>
            <div className="mt-1 text-sm text-muted-foreground">
              {gestureName !== '—'
                ? gestureCommands.find(g => g.gesture === gestureName)?.meaning || ''
                : '等待手势…'}
            </div>
          </div>
        </div>

        {/* 置信度 & 执行状态 */}
        <div className="flex flex-col justify-between rounded-2xl bg-primary/10 p-4 ring-1 ring-primary/20">
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-primary">当前识别</span>
            {confidence != null && (
              <span className={cn('font-mono text-xs', confidence >= 0.9 ? 'text-safe' : confidence >= 0.7 ? 'text-warn' : 'text-danger')}>
                {(confidence * 100).toFixed(1)}%
              </span>
            )}
          </div>
          <div className="h-2 overflow-hidden rounded-full bg-secondary">
            <div
              className="h-full rounded-full bg-primary transition-all duration-300"
              style={{ width: confidence != null ? `${(confidence * 100).toFixed(0)}%` : '0%' }}
            />
          </div>
          <div className="flex items-center gap-2 text-sm">
            {detStatus === '已执行' ? (
              <><CircleCheck className="h-4 w-4 text-safe" />已执行 · 刚刚</>
            ) : detStatus === '待确认' ? (
              <><AlertTriangle className="h-4 w-4 text-warn" />待确认</>
            ) : detStatus === '失败' ? (
              <><XCircle className="h-4 w-4 text-danger" />识别失败</>
            ) : (
              <><span className="h-2 w-2 animate-hmi-breathe rounded-full bg-primary" />识别中…</>
            )}
          </div>
        </div>
      </div>

      {/* 分类筛选 */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1">
        {categories.map((item) => (
          <button
            key={item}
            type="button"
            onClick={() => setCategory(item)}
            className={cn(
              'h-8 shrink-0 rounded-lg px-3 text-xs font-medium transition-colors',
              category === item ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground hover:text-foreground',
            )}
          >
            {item}
          </button>
        ))}
      </div>

      {/* 手势映射表 */}
      <div className="min-h-0 flex-1 overflow-y-auto rounded-xl ring-1 ring-border">
        <div className="grid grid-cols-[1fr_.85fr_.65fr_.65fr] bg-secondary/70 px-3 py-2 text-xs text-muted-foreground">
          <span>手势 / action_code</span><span>含义</span><span>分类</span><span>端点</span>
        </div>
        {filtered.map((command) => {
          const danger = command.actionCode === 'emergency_stop'
          const endpoint = endpointMap[command.actionCode] || '/api/agent/chat'
          return (
            <div
              key={`${command.gesture}-${command.actionCode}`}
              className={cn(
                'grid min-h-12 grid-cols-[1fr_.85fr_.65fr_.65fr] items-center border-t border-border px-3 py-2',
                danger && 'bg-danger/10',
              )}
            >
              <div className="min-w-0">
                <div className={cn('truncate font-mono text-xs font-medium', danger ? 'text-danger' : 'text-foreground')}>{command.gesture}</div>
                <div className="truncate font-mono text-[10px] text-muted-foreground">{command.actionCode}</div>
              </div>
              <div className="flex items-center gap-1.5 text-sm">
                {danger && <AlertTriangle className="h-4 w-4 text-danger" />}
                {command.meaning}
              </div>
              <span className="text-xs text-muted-foreground">{command.category}</span>
              <code className="truncate rounded bg-secondary/60 px-1 py-0.5 font-mono text-[10px] text-muted-foreground">{endpoint}</code>
            </div>
          )
        })}
      </div>

      {/* 底部状态栏 */}
      <div className="flex items-center justify-between rounded-xl bg-secondary/60 px-3 py-2.5">
        <div className="flex items-center gap-2 text-xs text-muted-foreground min-w-0">
          <Radio className="h-4 w-4 shrink-0" />
          <span className="truncate">
            {lastExecuted || (detection?.gesture ? `${detection.gesture} → ${gestureCommands.find(g => g.gesture === detection.gesture)?.actionCode || ''} → ${detStatus}` : '识别记录：等待手势输入')}
          </span>
        </div>
        <button
          type="button"
          onClick={() => setEnabled(!enabled)}
          className={cn('flex h-9 shrink-0 items-center gap-2 rounded-lg px-3 text-xs font-medium ml-2', enabled ? 'bg-primary/15 text-primary' : 'bg-secondary text-muted-foreground')}
        >
          <Hand className="h-4 w-4" /> {enabled ? '手势已开启' : '启用手势'}
        </button>
      </div>
    </div>
  )
}
