'use client'

import { useState } from 'react'
import { AppSidebar, type PanelKey } from '@/components/hmi/app-sidebar'
import { TopBar } from '@/components/hmi/top-bar'
import { SafetyPanel } from '@/components/hmi/safety-panel'
import { StatsPanel } from '@/components/hmi/stats-panel'
import { SettingsPanel } from '@/components/hmi/settings-panel'
import { MapArea } from '@/components/hmi/map-area'
import { AiPanel } from '@/components/hmi/ai-panel'
import { BottomBar } from '@/components/hmi/bottom-bar'
import { useTelemetry } from '@/components/hmi/use-telemetry'
import { initialAlerts, initialChat, initialStats, mockNav, type ChatMessage } from '@/lib/edgeguard'

export default function Page() {
  const [panel, setPanel] = useState<PanelKey>('safety')
  const [collapsed, setCollapsed] = useState(false)
  const [aiOpen, setAiOpen] = useState(true)
  const [messages, setMessages] = useState<ChatMessage[]>(initialChat)

  const telemetry = useTelemetry()

  const handleSend = (text: string) => {
    const userMsg: ChatMessage = { id: `u${Date.now()}`, role: 'user', text }
    setMessages((prev) => [...prev, userMsg])
    // 模拟 AI 回复。后续替换为 ENDPOINTS.chat 请求。
    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        {
          id: `a${Date.now()}`,
          role: 'assistant',
          text: `收到，正在为你处理「${text}」。这是模拟回复，后续将接入真实 AI 服务。`,
        },
      ])
    }, 700)
  }

  return (
    <main className="flex h-dvh w-full overflow-hidden bg-background text-foreground">
      <AppSidebar
        active={panel}
        onSelect={setPanel}
        collapsed={collapsed}
        onToggle={() => setCollapsed((v) => !v)}
      />

      <div className="flex min-w-0 flex-1 flex-col">
        <TopBar />

        <div className="flex min-h-0 flex-1">
          {/* 左侧内容面板：随侧栏切换 */}
          <section className="w-[300px] shrink-0 border-r border-border">
            {panel === 'safety' && <SafetyPanel telemetry={telemetry} alerts={initialAlerts} />}
            {panel === 'stats' && <StatsPanel stats={initialStats} />}
            {panel === 'settings' && <SettingsPanel />}
          </section>

          {/* 中央地图区 */}
          <section className="min-w-0 flex-1 p-3">
            <MapArea nav={mockNav} />
          </section>

          {/* 右侧 AI 区 */}
          {aiOpen && (
            <AiPanel messages={messages} onSend={handleSend} onClose={() => setAiOpen(false)} />
          )}
        </div>

        <BottomBar aiOpen={aiOpen} onOpenAi={() => setAiOpen(true)} />
      </div>
    </main>
  )
}
