'use client'

import { useRef, useState } from 'react'
import {
  AlertTriangle, ArrowDown, ChevronDown, ChevronRight, CircleCheck,
  Cloud, MapPin, Mic, Navigation, Send, Shield, Slash, Sparkles,
  Volume2, X, XCircle,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import {
  agentRoutes, mockAgentResults, mockAgentTrace, quickReplies,
  safetyGateMap,
  type AgentResult, type AgentRoute, type AgentTraceStep, type ChatMessage,
  type SafetyLevel,
} from '@/lib/edgeguard'

const resultIcon: Record<AgentResult['type'], typeof MapPin> = { poi: MapPin, weather: Cloud, route: Navigation }
const phaseLabel: Record<AgentTraceStep['phase'], string> = { perceive: '感知', safety_gate: '安全门控', agent: '决策', tool: '工具', result: '结果' }

const statusIcon = (status: AgentTraceStep['status']) => {
  switch (status) {
    case 'done': return <CircleCheck className="h-4 w-4 shrink-0 text-safe" />
    case 'running': return <span className="h-4 w-4 shrink-0 animate-hmi-breathe rounded-full bg-primary" />
    case 'failed': return <XCircle className="h-4 w-4 shrink-0 text-danger" />
    case 'cancelled': return <Slash className="h-4 w-4 shrink-0 text-muted-foreground" />
    case 'degraded': return <ArrowDown className="h-4 w-4 shrink-0 text-warn" />
    default: return <span className="h-4 w-4 shrink-0 rounded-full border border-muted-foreground/40" />
  }
}

const safetyGateStyle = (level: SafetyLevel) => {
  const gate = safetyGateMap[level]
  const isFull = gate.toolAvailability === 'full'
  const isReadonly = gate.toolAvailability === 'readonly'
  return {
    label: gate.label,
    bg: isFull ? 'bg-safe/15 text-safe' : isReadonly ? 'bg-danger/15 text-danger' : 'bg-warn/15 text-warn',
    icon: isFull ? Shield : isReadonly ? AlertTriangle : Shield,
  }
}

export function AiPanel({ messages, onSend, onClose }: { messages: ChatMessage[]; onSend: (t: string) => void; onClose: () => void }) {
  const [input, setInput] = useState('')
  const [recording, setRecording] = useState(false)
  const [advanced, setAdvanced] = useState(false)
  const [route, setRoute] = useState<AgentRoute>('auto')
  const [routeOpen, setRouteOpen] = useState(false)
  const [traceOpen, setTraceOpen] = useState(false)
  const pressTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const [pressing, setPressing] = useState(false)
  const [safetyLevel, setSafetyLevel] = useState<SafetyLevel>('normal')

  const submit = (text: string) => {
    const t = text.trim()
    if (!t) return
    onSend(t)
    setInput('')
    // 模拟：根据消息内容切换安全级别（演示用）
    if (t.includes('疲劳') || t.includes('累了')) setSafetyLevel('attn_declining')
    else if (t.includes('分心')) setSafetyLevel('distracted')
    else if (t.includes('危险') || t.includes('紧急')) setSafetyLevel('dangerous')
    else setSafetyLevel('normal')
  }

  // 长按状态区进入高级模式（带视觉反馈）
  const startPress = () => {
    setPressing(true)
    pressTimer.current = setTimeout(() => { setAdvanced(true); setPressing(false) }, 600)
  }
  const endPress = () => { setPressing(false); if (pressTimer.current) clearTimeout(pressTimer.current) }

  const lastAssistant = [...messages].reverse().find((m) => m.role === 'assistant')
  const activeRoute = agentRoutes.find((r) => r.id === route)!
  const readOnly = route === 'readonly'
  const gate = safetyGateStyle(readOnly ? 'dangerous' : safetyLevel)

  return (
    <div className="flex h-full w-[360px] shrink-0 flex-col border-l border-border bg-card/70">
      {/* header */}
      <div className="flex items-center justify-between px-3 pt-3">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/15"><Sparkles className="h-4 w-4 text-primary" /></div>
          <span className="text-sm font-semibold">AI 副驾</span>
        </div>
        <div className="flex items-center gap-1">
          <button type="button" onClick={() => setAdvanced((v) => !v)} className={cn('rounded-lg px-2 py-1 text-xs font-medium transition-colors', advanced ? 'bg-primary/15 text-primary' : 'text-muted-foreground hover:bg-secondary')}>
            {advanced ? '高级' : '普通'}
          </button>
          <button type="button" onClick={onClose} aria-label="收起 AI 面板" className="flex h-8 w-8 items-center justify-center rounded-lg text-muted-foreground hover:bg-secondary hover:text-foreground"><X className="h-4 w-4" /></button>
        </div>
      </div>

      {/* 状态指示器：长按进入高级（带视觉反馈） */}
      <button
        type="button"
        onPointerDown={startPress}
        onPointerUp={endPress}
        onPointerLeave={endPress}
        onContextMenu={(e) => e.preventDefault()}
        className={cn(
          'mx-3 mt-3 flex items-center gap-3 rounded-xl bg-secondary/60 px-3 py-2.5 text-left transition-all',
          pressing && 'ring-2 ring-primary/50 scale-[0.98]',
          'hover:bg-secondary',
        )}
      >
        <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/15">
          <span className={cn('h-3 w-3 rounded-full', pressing ? 'animate-hmi-breathe bg-primary' : 'animate-hmi-breathe bg-primary')} />
        </span>
        <span className="min-w-0 flex-1">
          <span className="block text-xs text-muted-foreground">
            {route === 'auto' ? '系统自动选择最优 Agent' : '当前路由'}
          </span>
          <span className="block truncate text-sm font-medium text-foreground">{activeRoute.label}</span>
        </span>
        <span className={cn('flex items-center gap-1 rounded-md px-2 py-1 text-[10px] font-medium', gate.bg)}>
          <gate.icon className="h-3 w-3" />{gate.label}
        </span>
      </button>

      {!advanced && (
        <div className="flex flex-col gap-0.5 px-3 pt-1.5">
          <p className="text-[10px] text-muted-foreground">长按上方状态可进入高级模式</p>
          {/* 被禁工具提示 */}
          {gate.label !== '全工具' && (
            <p className="text-[10px] text-warn">
              受限工具：{safetyGateMap[safetyLevel].blockedTools.slice(0, 4).join('、')}
              {safetyGateMap[safetyLevel].blockedTools.length > 4 ? '…' : ''}
            </p>
          )}
        </div>
      )}

      {/* 高级模式：路由选择 + 执行轨迹 */}
      {advanced && (
        <div className="mx-3 mt-2 flex flex-col gap-2">
          <div className="relative">
            <button type="button" onClick={() => setRouteOpen((v) => !v)} className="flex w-full items-center justify-between rounded-lg bg-secondary px-3 py-2 text-sm">
              <span>路由：<span className="font-medium text-primary">{activeRoute.label}</span></span>
              <ChevronDown className={cn('h-4 w-4 transition-transform', routeOpen && 'rotate-180')} />
            </button>
            {routeOpen && (
              <div className="absolute z-10 mt-1 w-full overflow-hidden rounded-lg border border-border bg-popover shadow-xl">
                {agentRoutes.map((r) => (
                  <button key={r.id} type="button" onClick={() => { setRoute(r.id); setRouteOpen(false) }} className={cn('flex w-full flex-col gap-0.5 px-3 py-2 text-left transition-colors hover:bg-accent', route === r.id && 'bg-primary/10')}>
                    <span className="text-sm font-medium">{r.label}</span>
                    <span className="text-xs text-muted-foreground">{r.description}</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* 当前安全门控详情 */}
          <div className="rounded-lg bg-secondary/40 p-2.5 text-xs">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">安全门控</span>
              <span className={cn('rounded-md px-2 py-0.5 font-medium', gate.bg)}>
                <gate.icon className="mr-1 inline h-3 w-3" />{gate.label} · {safetyLevel}
              </span>
            </div>
            <div className="mt-1.5 grid grid-cols-2 gap-1 text-[10px] text-muted-foreground">
              <span>可用：{safetyGateMap[safetyLevel].allowedTools.length} 个工具</span>
              <span>禁用：{safetyGateMap[safetyLevel].blockedTools.length} 个工具</span>
            </div>
          </div>

          <button type="button" onClick={() => setTraceOpen((v) => !v)} className="flex items-center justify-between rounded-lg bg-secondary/60 px-3 py-2 text-xs text-muted-foreground">
            <span>执行轨迹（系统记录）</span>
            <ChevronDown className={cn('h-4 w-4 transition-transform', traceOpen && 'rotate-180')} />
          </button>
          {traceOpen && (
            <div className="flex flex-col gap-1">
              {mockAgentTrace.map((step, index) => (
                <div key={step.id} className="flex flex-col gap-1 rounded-lg bg-secondary/40 px-3 py-2">
                  <div className="flex items-center gap-2.5">
                    {statusIcon(step.status)}
                    <span className="w-14 shrink-0 font-mono text-[10px] text-muted-foreground">{index + 1}.{phaseLabel[step.phase]}</span>
                    <span className={cn('min-w-0 flex-1 truncate text-xs', step.status === 'pending' ? 'text-muted-foreground' : 'text-foreground')}>{step.detail}</span>
                    {step.durationMs != null && <span className="shrink-0 font-mono text-[10px] text-muted-foreground">{step.durationMs}ms</span>}
                  </div>
                  {/* 工具调用实参和返回值 */}
                  {step.toolName && (
                    <div className="ml-[4.5rem] flex flex-col gap-0.5 text-[10px]">
                      <span className="text-muted-foreground">
                        入参：<code className="rounded bg-secondary px-1 font-mono text-primary">{JSON.stringify(step.toolArgs)}</code>
                      </span>
                      {step.toolResult && (
                        <span className={cn(step.status === 'failed' ? 'text-danger' : 'text-safe')}>{step.toolResult}</span>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 对话主体 */}
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto p-3">
        {lastAssistant && (
          <div className="rounded-2xl bg-primary/10 p-3 ring-1 ring-primary/20">
            <div className="mb-1.5 flex items-center gap-2">
              <Sparkles className="h-4 w-4 text-primary" /><span className="text-xs font-medium text-primary">EdgeGuard</span>
              <button type="button" aria-label="朗读回复" className="ml-auto flex h-6 w-6 items-center justify-center rounded-md text-primary hover:bg-primary/15"><Volume2 className="h-3.5 w-3.5" /></button>
            </div>
            <p className="text-lg leading-relaxed text-pretty">{lastAssistant.text}</p>
          </div>
        )}
        <div className="flex flex-col gap-2">
          {messages.map((m) => (
            <div key={m.id} className={cn('flex', m.role === 'user' ? 'justify-end' : 'justify-start')}>
              <div className={cn('max-w-[85%] rounded-2xl px-3 py-2 text-sm leading-relaxed', m.role === 'user' ? 'bg-primary text-primary-foreground' : 'bg-secondary text-foreground')}>{m.text}</div>
            </div>
          ))}
        </div>

        {advanced && (
          <div className="flex flex-col gap-2">
            <span className="text-xs font-medium text-muted-foreground">结果卡片</span>
            {mockAgentResults.map((r) => {
              const Icon = resultIcon[r.type]
              return (
                <button key={r.id} type="button" className="flex items-center gap-3 rounded-xl bg-card p-3 text-left hover:bg-accent">
                  <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary/12"><Icon className="h-4 w-4 text-primary" /></span>
                  <span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium">{r.title}</span><span className="block truncate text-xs text-muted-foreground">{r.subtitle}</span></span>
                  <span className="shrink-0 text-xs text-primary">{r.meta}</span>
                  <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
                </button>
              )
            })}
          </div>
        )}
      </div>

      {/* input dock */}
      <div className="border-t border-border p-3">
        <div className="mb-2 flex flex-wrap gap-1.5">
          {quickReplies.map((q) => (
            <button key={q} type="button" onClick={() => submit(q)} className="rounded-full bg-secondary px-2.5 py-1 text-xs text-muted-foreground hover:bg-accent hover:text-foreground">{q}</button>
          ))}
        </div>
        <div className="flex items-center gap-2">
          <button type="button" onClick={() => setRecording((v) => !v)} aria-label={recording ? '停止录音' : '开始语音'} className={cn('flex h-11 w-11 shrink-0 items-center justify-center rounded-xl transition-colors', recording ? 'animate-hmi-breathe bg-danger text-primary-foreground' : 'bg-primary/15 text-primary hover:bg-primary/25')}><Mic className="h-5 w-5" /></button>
          <input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.nativeEvent.isComposing && e.keyCode !== 229) submit(input) }} placeholder="输入或说出指令…" className="h-11 flex-1 rounded-xl bg-secondary px-3 text-sm outline-none placeholder:text-muted-foreground focus:ring-1 focus:ring-primary/40" />
          <button type="button" onClick={() => submit(input)} aria-label="发送" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground hover:opacity-90"><Send className="h-5 w-5" /></button>
        </div>
      </div>
    </div>
  )
}
