'use client'

import { cn } from '@/lib/utils'
import type { SafetyLevel } from '@/lib/edgeguard'

const levelColor: Record<SafetyLevel, string> = {
  safe: 'var(--safe)',
  warn: 'var(--warn)',
  danger: 'var(--danger)',
}

const levelLabel: Record<SafetyLevel, string> = {
  safe: '专注',
  warn: '注意',
  danger: '警告',
}

export function AttentionRing({
  value,
  level,
  size = 176,
}: {
  value: number
  level: SafetyLevel
  size?: number
}) {
  const stroke = 12
  const radius = (size - stroke) / 2
  const circumference = 2 * Math.PI * radius
  const offset = circumference - (value / 100) * circumference
  const color = levelColor[level]

  return (
    <div
      className="relative flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      <svg width={size} height={size} className="-rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="var(--secondary)"
          strokeWidth={stroke}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={stroke}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          style={{
            transition: 'stroke-dashoffset 0.8s ease, stroke 0.4s ease',
            filter: `drop-shadow(0 0 6px color-mix(in oklch, ${color} 60%, transparent))`,
          }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span
          className="font-mono text-5xl font-semibold tabular-nums leading-none"
          style={{ color }}
        >
          {Math.round(value)}
        </span>
        <span className="mt-1 text-xs text-muted-foreground">注意力分数</span>
        <span
          className={cn(
            'mt-2 rounded-full px-2.5 py-0.5 text-xs font-medium',
          )}
          style={{
            color,
            backgroundColor: `color-mix(in oklch, ${color} 18%, transparent)`,
          }}
        >
          {levelLabel[level]}
        </span>
      </div>
    </div>
  )
}
