'use client'

import { useEffect, useState } from 'react'
import { Cloud, Wifi, Settings } from 'lucide-react'

export function TopBar() {
  const [now, setNow] = useState<Date | null>(null)

  useEffect(() => {
    setNow(new Date())
    const t = setInterval(() => setNow(new Date()), 1000 * 30)
    return () => clearInterval(t)
  }, [])

  const time = now
    ? now.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false })
    : '--:--'
  const date = now
    ? now.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'short' })
    : ''

  return (
    <header className="flex h-12 shrink-0 items-center justify-between border-b border-border px-4">
      <div className="flex items-center gap-3">
        <span className="text-sm font-semibold tracking-wide">
          Edge<span className="text-primary">Guard</span>
        </span>
        <span className="rounded-full bg-safe/15 px-2 py-0.5 text-[11px] font-medium text-safe">
          监测中
        </span>
      </div>

      <div className="flex items-center gap-2 font-mono text-lg font-medium tabular-nums">
        <span>{time}</span>
        <span className="text-xs font-sans font-normal text-muted-foreground">{date}</span>
      </div>

      <div className="flex items-center gap-4 text-sm text-muted-foreground">
        <div className="flex items-center gap-1.5">
          <Cloud className="h-4 w-4" />
          <span>22°C 多云</span>
        </div>
        <div className="flex items-center gap-1.5 text-safe">
          <Wifi className="h-4 w-4" />
          <span className="text-xs">在线</span>
        </div>
        <button
          type="button"
          aria-label="设置"
          className="flex h-8 w-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground"
        >
          <Settings className="h-4 w-4" />
        </button>
      </div>
    </header>
  )
}
