'use client'

import { useState } from 'react'
import { Power, Snowflake, Wind, RotateCw, Zap, Car } from 'lucide-react'
import { cn } from '@/lib/utils'
import { initialHvac, type HvacState, type HvacMode } from '@/lib/edgeguard'

// TODO: 接入 POST /api/ac/command
// action_code 映射: TurnOnAC / TurnOffAC / temp_up / temp_down / set
// 请求体: { command: "set", temperature: 22.5, mode: "face", fanSpeed: 3 }
// 空调状态模型: backend/main.py _ac_state = { power, temperature, mode, fanSpeed }

const modeLabels: { id: HvacMode; label: string; icon: typeof Wind }[] = [
  { id: 'face', label: '吹脸', icon: Wind },
  { id: 'face-feet', label: '吹脸+脚', icon: Wind },
  { id: 'feet', label: '吹脚', icon: Wind },
  { id: 'front-defrost', label: '前挡除雾', icon: Wind },
  { id: 'rear-defrost', label: '后挡除雾', icon: Car },
]

export function ClimateControl() {
  const [hvac, setHvac] = useState<HvacState>(initialHvac)
  const set = (patch: Partial<HvacState>) => setHvac((s) => ({ ...s, ...patch }))

  const stepTemp = (zone: 'driver' | 'passenger', delta: number) => {
    setHvac((s) => {
      const clamp = (v: number) => Math.min(30, Math.max(16, Math.round(v * 2) / 2))
      if (s.sync) {
        const t = clamp(s.driverTemp + delta)
        return { ...s, driverTemp: t, passengerTemp: t }
      }
      return zone === 'driver'
        ? { ...s, driverTemp: clamp(s.driverTemp + delta) }
        : { ...s, passengerTemp: clamp(s.passengerTemp + delta) }
    })
  }

  return (
    <div className={cn('flex flex-col gap-4', !hvac.power && 'opacity-60')}>
      {/* 顶部：总开关 + SYNC */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-base font-semibold">双区空调</span>
          <span className="rounded-md bg-secondary px-2 py-0.5 text-xs text-muted-foreground">
            {hvac.auto ? 'AUTO' : '手动'} · {hvac.fanSpeed} 档
          </span>
        </div>
        <button
          type="button"
          onClick={() => set({ power: !hvac.power })}
          aria-label="空调总开关"
          className={cn(
            'flex h-10 w-10 items-center justify-center rounded-xl transition-colors',
            hvac.power ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground',
          )}
        >
          <Power className="h-5 w-5" />
        </button>
      </div>

      {/* 双区温度 */}
      <div className="grid grid-cols-[1fr_auto_1fr] items-stretch gap-3">
        <TempZone label="主驾" value={hvac.driverTemp} onStep={(d) => stepTemp('driver', d)} />
        <div className="flex flex-col items-center justify-center gap-2">
          <button
            type="button"
            onClick={() => set({ sync: !hvac.sync, passengerTemp: hvac.driverTemp })}
            className={cn(
              'flex flex-col items-center gap-1 rounded-xl px-3 py-2 text-xs font-medium transition-colors',
              hvac.sync ? 'bg-primary/15 text-primary' : 'bg-secondary text-muted-foreground',
            )}
          >
            <RotateCw className="h-4 w-4" />
            SYNC
          </button>
        </div>
        <TempZone label="副驾" value={hvac.passengerTemp} onStep={(d) => stepTemp('passenger', d)} dimmed={hvac.sync} />
      </div>

      {/* 风速 1-5 */}
      <div>
        <div className="mb-1.5 flex items-center gap-1.5 text-xs text-muted-foreground">
          <Wind className="h-3.5 w-3.5" /> 风速
        </div>
        <div className="flex gap-1.5">
          {[1, 2, 3, 4, 5].map((n) => (
            <button
              key={n}
              type="button"
              onClick={() => set({ fanSpeed: n as HvacState['fanSpeed'], auto: false })}
              className={cn(
                'h-9 flex-1 rounded-lg text-sm font-medium tabular-nums transition-colors',
                hvac.fanSpeed >= n ? 'bg-primary/80 text-primary-foreground' : 'bg-secondary text-muted-foreground hover:bg-accent',
              )}
            >
              {n}
            </button>
          ))}
        </div>
      </div>

      {/* 送风模式（3×2 网格，5 种模式） */}
      <div className="grid grid-cols-3 gap-1.5">
        {modeLabels.map((m) => {
          const Icon = m.icon
          return (
            <button
              key={m.id}
              type="button"
              onClick={() => set({ mode: m.id })}
              className={cn(
                'flex h-10 items-center justify-center gap-1.5 rounded-lg text-sm font-medium transition-colors',
                hvac.mode === m.id ? 'bg-primary/15 text-primary ring-1 ring-primary/30' : 'bg-secondary text-muted-foreground hover:bg-accent',
              )}
            >
              <Icon className="h-3.5 w-3.5" />
              {m.label}
            </button>
          )
        })}
      </div>

      {/* 开关行 */}
      <div className="grid grid-cols-3 gap-1.5">
        <ToggleChip icon={Zap} label="AUTO" on={hvac.auto} onClick={() => set({ auto: !hvac.auto })} />
        <ToggleChip icon={Snowflake} label="A/C" on={hvac.ac} onClick={() => set({ ac: !hvac.ac })} />
        <ToggleChip
          icon={RotateCw}
          label={hvac.circulation === 'inside' ? '内循环' : '外循环'}
          on={hvac.circulation === 'inside'}
          onClick={() => set({ circulation: hvac.circulation === 'inside' ? 'outside' : 'inside' })}
        />
      </div>
    </div>
  )
}

function TempZone({ label, value, onStep, dimmed }: { label: string; value: number; onStep: (d: number) => void; dimmed?: boolean }) {
  return (
    <div className={cn('flex flex-col items-center gap-2 rounded-2xl bg-secondary/50 p-3', dimmed && 'opacity-70')}>
      <span className="text-xs text-muted-foreground">{label}</span>
      <div className="font-mono text-4xl font-semibold tabular-nums text-primary">{value.toFixed(1)}°</div>
      <div className="flex w-full gap-1.5">
        <button
          type="button"
          aria-label={`${label}降温`}
          onClick={() => onStep(-0.5)}
          className="h-10 flex-1 rounded-lg bg-card text-lg font-medium hover:bg-accent"
        >
          −
        </button>
        <button
          type="button"
          aria-label={`${label}升温`}
          onClick={() => onStep(0.5)}
          className="h-10 flex-1 rounded-lg bg-card text-lg font-medium hover:bg-accent"
        >
          +
        </button>
      </div>
    </div>
  )
}

function ToggleChip({ icon: Icon, label, on, onClick }: { icon: typeof Wind; label: string; on: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'flex h-10 items-center justify-center gap-2 rounded-lg text-sm font-medium transition-colors',
        on ? 'bg-primary/15 text-primary ring-1 ring-primary/30' : 'bg-secondary text-muted-foreground hover:bg-accent',
      )}
    >
      <Icon className="h-4 w-4" />
      {label}
    </button>
  )
}
