'use client'

import { useState } from 'react'
import { Hand, Music, Pause, Play, SkipBack, SkipForward, Sparkles, Wind, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { ClimateControl } from './climate-control'
import { GestureControl } from './gesture-control'

type Drawer = 'climate' | 'music' | 'gesture' | null

export function BottomBar({ aiOpen, onOpenAi }: { aiOpen: boolean; onOpenAi: () => void }) {
  const [drawer, setDrawer] = useState<Drawer>(null)
  const [playing, setPlaying] = useState(true)
  const toggle = (next: Drawer) => setDrawer((current) => current === next ? null : next)

  return (
    <div className="relative z-30 shrink-0">
      {drawer && (
        <div className="animate-slide-in-bottom absolute inset-x-3 bottom-full mb-2 max-h-[72vh] overflow-hidden rounded-2xl border border-border bg-card shadow-2xl">
          <div className="flex h-12 items-center justify-between border-b border-border px-4">
            <div className="flex items-center gap-2">
              {drawer === 'climate' && <Wind className="h-4 w-4 text-primary" />}
              {drawer === 'music' && <Music className="h-4 w-4 text-primary" />}
              {drawer === 'gesture' && <Hand className="h-4 w-4 text-primary" />}
              <span className="text-sm font-semibold">
                {drawer === 'climate' ? '车辆温控' : drawer === 'music' ? '媒体中心' : 'EdgeGuard 手势指令'}
              </span>
              <span className="text-xs text-muted-foreground">控制变更将发送至车辆接口</span>
            </div>
            <button type="button" onClick={() => setDrawer(null)} aria-label="关闭控制抽屉" className="flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-secondary hover:text-foreground">
              <X className="h-4 w-4" />
            </button>
          </div>
          <div className={cn('overflow-y-auto p-4', drawer === 'gesture' ? 'max-h-[60vh]' : 'max-h-[calc(72vh-48px)]')}>
            {drawer === 'climate' && <ClimateControl />}
            {drawer === 'gesture' && <GestureControl />}
            {drawer === 'music' && (
              <div className="flex items-center gap-5 rounded-2xl bg-secondary/60 p-5">
                <div className="flex h-20 w-20 items-center justify-center rounded-2xl bg-primary/15"><Music className="h-8 w-8 text-primary" /></div>
                <div className="min-w-0 flex-1">
                  <div className="text-lg font-semibold">夜间驾驶电台</div>
                  <div className="mt-1 text-sm text-muted-foreground">Ambient · 轻音乐</div>
                  <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-card"><div className="h-full w-2/5 bg-primary" /></div>
                </div>
                <div className="flex items-center gap-2">
                  <MediaButton label="上一首"><SkipBack className="h-5 w-5" /></MediaButton>
                  <button type="button" onClick={() => setPlaying((v) => !v)} aria-label={playing ? '暂停' : '播放'} className="flex h-12 w-12 items-center justify-center rounded-full bg-primary text-primary-foreground">
                    {playing ? <Pause className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                  </button>
                  <MediaButton label="下一首"><SkipForward className="h-5 w-5" /></MediaButton>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <div className="flex h-16 items-center gap-2 border-t border-border bg-card/95 px-3 backdrop-blur-xl">
        <QuickButton icon={Wind} label="22.5° / 23° · 2档" meta="双区空调" active={drawer === 'climate'} onClick={() => toggle('climate')} />
        <QuickButton icon={Music} label={playing ? '夜间驾驶电台' : '媒体已暂停'} meta="媒体" active={drawer === 'music'} onClick={() => toggle('music')} />
        <QuickButton icon={Hand} label="swipe_right · 96.8%" meta="手势在线" active={drawer === 'gesture'} onClick={() => toggle('gesture')} />
        <div className="ml-auto">
          {!aiOpen && (
            <button type="button" onClick={onOpenAi} className="flex h-11 items-center gap-2 rounded-xl bg-primary/15 px-4 text-primary hover:bg-primary/25">
              <Sparkles className="h-5 w-5" /><span className="text-sm font-medium">AI 副驾</span>
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

function QuickButton({ icon: Icon, label, meta, active, onClick }: { icon: typeof Wind; label: string; meta: string; active: boolean; onClick: () => void }) {
  return (
    <button type="button" onClick={onClick} className={cn('flex h-11 min-w-0 items-center gap-2 rounded-xl px-3 transition-colors', active ? 'bg-primary/15 text-primary ring-1 ring-primary/30' : 'bg-secondary/60 text-muted-foreground hover:bg-secondary hover:text-foreground')}>
      <Icon className="h-5 w-5 shrink-0" />
      <span className="min-w-0 text-left"><span className="block text-[10px] leading-none text-muted-foreground">{meta}</span><span className="mt-1 block truncate text-xs font-medium">{label}</span></span>
    </button>
  )
}

function MediaButton({ label, children }: { label: string; children: React.ReactNode }) {
  return <button type="button" aria-label={label} className="flex h-11 w-11 items-center justify-center rounded-full bg-card text-muted-foreground hover:bg-accent hover:text-foreground">{children}</button>
}
