'use client'

import { useState } from 'react'
import { cn } from '@/lib/utils'

function Toggle({
  label,
  desc,
  defaultOn,
}: {
  label: string
  desc: string
  defaultOn?: boolean
}) {
  const [on, setOn] = useState(!!defaultOn)
  return (
    <div className="flex items-center justify-between rounded-xl bg-secondary/50 p-3">
      <div className="min-w-0 pr-3">
        <div className="text-sm font-medium">{label}</div>
        <div className="text-xs text-muted-foreground">{desc}</div>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={on}
        aria-label={label}
        onClick={() => setOn((v) => !v)}
        className={cn(
          'relative h-7 w-12 shrink-0 rounded-full transition-colors',
          on ? 'bg-primary' : 'bg-muted',
        )}
      >
        <span
          className={cn(
            'absolute top-1 h-5 w-5 rounded-full bg-background transition-transform',
            on ? 'translate-x-6' : 'translate-x-1',
          )}
        />
      </button>
    </div>
  )
}

export function SettingsPanel() {
  return (
    <div className="flex h-full flex-col gap-4 overflow-y-auto p-4">
      <h2 className="text-sm font-semibold text-muted-foreground">设置</h2>

      <div className="flex flex-col gap-2">
        <Toggle label="注意力监测" desc="实时检测驾驶员注意力" defaultOn />
        <Toggle label="疲劳预警" desc="疲劳超阈值时语音提醒" defaultOn />
        <Toggle label="视线追踪" desc="监测视线是否偏离路面" defaultOn />
        <Toggle label="语音助手" desc="启用 AI 语音交互" defaultOn />
        <Toggle label="手势控制" desc="通过手势控制车机功能" />
        <Toggle label="夜间模式" desc="低光环境自动降低亮度" defaultOn />
      </div>

      <div className="flex flex-col gap-2 rounded-xl bg-card p-4">
        <span className="text-xs font-medium text-muted-foreground">告警灵敏度</span>
        <div className="flex gap-2">
          {['低', '中', '高'].map((lv, i) => (
            <button
              key={lv}
              type="button"
              className={cn(
                'flex-1 rounded-lg py-2 text-sm transition-colors',
                i === 1
                  ? 'bg-primary/15 text-primary ring-1 ring-primary/30'
                  : 'bg-secondary text-muted-foreground hover:text-foreground',
              )}
            >
              {lv}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}
