'use client'

import { AlertTriangle, CircleCheck, CircleAlert, Eye, Activity } from 'lucide-react'
import { AttentionRing } from './attention-ring'
import { cn } from '@/lib/utils'
import type { SafetyAlert, SafetyLevel, Telemetry } from '@/lib/edgeguard'

const levelStyles: Record<SafetyLevel, { text: string; bg: string; icon: typeof CircleCheck }> = {
  normal: { text: 'text-safe', bg: 'bg-safe/12', icon: CircleCheck },
  attn_declining: { text: 'text-warn', bg: 'bg-warn/12', icon: CircleAlert },
  distracted: { text: 'text-warn', bg: 'bg-warn/12', icon: CircleAlert },
  dangerous: { text: 'text-danger', bg: 'bg-danger/15', icon: AlertTriangle },
}

function Metric({
  icon: Icon,
  label,
  value,
  suffix,
}: {
  icon: typeof Eye
  label: string
  value: number
  suffix?: string
}) {
  return (
    <div className="flex flex-col gap-1 rounded-xl bg-secondary/50 p-3">
      <div className="flex items-center gap-1.5 text-muted-foreground">
        <Icon className="h-3.5 w-3.5" />
        <span className="text-[11px]">{label}</span>
      </div>
      <div className="font-mono text-xl font-semibold tabular-nums">
        {value}
        {suffix && <span className="ml-0.5 text-xs font-normal text-muted-foreground">{suffix}</span>}
      </div>
    </div>
  )
}

export function SafetyPanel({
  telemetry,
  alerts,
}: {
  telemetry: Telemetry
  alerts: SafetyAlert[]
}) {
  return (
    <div className="flex h-full flex-col gap-4 overflow-y-auto p-4">
      <h2 className="text-sm font-semibold text-muted-foreground">安全监控</h2>

      <div className="flex flex-col items-center rounded-2xl bg-card p-4">
        <AttentionRing value={telemetry.attention} level={telemetry.level} />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <Metric icon={Activity} label="疲劳程度" value={telemetry.fatigue} suffix="%" />
        <Metric icon={Eye} label="视线在路" value={telemetry.gazeOnRoad} suffix="%" />
      </div>

      <div className="flex flex-col gap-2">
        <h3 className="text-xs font-medium text-muted-foreground">实时告警</h3>
        {alerts.map((a) => {
          const s = levelStyles[a.level]
          const Icon = s.icon
          return (
            <div
              key={a.id}
              className={cn(
                'flex items-start gap-3 rounded-xl p-3',
                s.bg,
                a.level === 'dangerous' && 'animate-hmi-pulse',
              )}
            >
              <Icon className={cn('mt-0.5 h-5 w-5 shrink-0', s.text)} />
              <div className="min-w-0 flex-1">
                <div className="flex items-center justify-between gap-2">
                  <span className={cn('text-sm font-medium', s.text)}>{a.title}</span>
                  <span className="shrink-0 text-[10px] text-muted-foreground">{a.time}</span>
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">{a.detail}</p>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
