'use client'

import { Clock, Eye, Activity } from 'lucide-react'
import type { DrivingStats } from '@/lib/edgeguard'

function StatCard({
  icon: Icon,
  label,
  value,
  unit,
}: {
  icon: typeof Clock
  label: string
  value: string | number
  unit?: string
}) {
  return (
    <div className="flex flex-col gap-1.5 rounded-xl bg-secondary/50 p-3">
      <div className="flex items-center gap-1.5 text-muted-foreground">
        <Icon className="h-3.5 w-3.5" />
        <span className="text-[11px]">{label}</span>
      </div>
      <div className="font-mono text-2xl font-semibold tabular-nums">
        {value}
        {unit && <span className="ml-1 text-xs font-normal text-muted-foreground">{unit}</span>}
      </div>
    </div>
  )
}

export function StatsPanel({ stats }: { stats: DrivingStats }) {
  const max = Math.max(...stats.fatigueTrend, 1)

  return (
    <div className="flex h-full flex-col gap-4 overflow-y-auto p-4">
      <h2 className="text-sm font-semibold text-muted-foreground">驾驶统计</h2>

      <div className="flex flex-col items-center gap-1 rounded-2xl bg-card p-5">
        <span className="text-xs text-muted-foreground">本次驾驶评分</span>
        <span className="font-mono text-5xl font-semibold tabular-nums text-primary">
          {stats.score}
        </span>
        <span className="text-xs text-safe">表现优秀 · 继续保持</span>
      </div>

      <div className="grid grid-cols-3 gap-3">
        <StatCard icon={Clock} label="驾驶时长" value={stats.durationMin} unit="分" />
        <StatCard icon={Eye} label="分心次数" value={stats.distractionCount} unit="次" />
        <StatCard icon={Activity} label="打哈欠" value={stats.yawnCount} unit="次" />
      </div>

      <div className="flex flex-col gap-2 rounded-xl bg-card p-4">
        <span className="text-xs font-medium text-muted-foreground">疲劳趋势</span>
        <div className="flex h-24 items-end gap-1.5">
          {stats.fatigueTrend.map((v, i) => (
            <div
              key={i}
              className="flex-1 rounded-t-sm bg-primary/70 transition-all"
              style={{ height: `${(v / max) * 100}%` }}
              title={`${v}%`}
            />
          ))}
        </div>
        <span className="text-[10px] text-muted-foreground">近 1 小时采样</span>
      </div>
    </div>
  )
}
